function asArray(item) {
  const json = item.json;
  if (Array.isArray(json)) return json;
  if (json && Array.isArray(json.data)) return json.data;
  return [];
}

const since = new Date(Date.now() - 60*60*1000);
const recent = $input.all().flatMap(asArray).filter((e) => {
  const stoppedAt = e.stoppedAt || e.stopped_at;
  return stoppedAt && new Date(stoppedAt) >= since;
});

const byWorkflow = {};
for (const e of recent) {
  const name = e.workflowData?.name || e.workflowName || e.workflowId || 'unknown workflow';
  byWorkflow[name] = (byWorkflow[name] || 0) + 1;
}

const summary = Object.entries(byWorkflow).map(([name, count]) => `${name} (${count})`).join(', ');

return [{ json: { failureCount: recent.length, summary } }];
